sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', summary: {} };
  try {
    var results = JSON.parse(inputs.upgrade_results);
    var planId = inputs.plan_id;

    var summary = {
      plan_id: planId,
      completion_time: new GlideDateTime().getDisplayValue(),
      total_attempted: 0,
      successful: 0,
      failed: 0,
      skipped: 0,
      plugins: [],
      recommendations: []
    };

    for (var i = 0; i < results.length; i++) {
      var r = results[i];
      summary.total_attempted++;

      var pluginSummary = {
        name: r.plugin_name || r.name,
        previous_version: r.previous_version || 'N/A',
        new_version: r.new_version || r.target_version || 'N/A',
        status: r.status || 'unknown'
      };

      if (r.status === 'completed' || r.status === 'success') {
        summary.successful++;
        pluginSummary.status = 'Success';
      } else if (r.status === 'failed' || r.status === 'error') {
        summary.failed++;
        pluginSummary.status = 'Failed';
        pluginSummary.failure_reason = r.error || r.message || 'See failure logs';
      } else if (r.status === 'skipped') {
        summary.skipped++;
        pluginSummary.status = 'Skipped';
        pluginSummary.skip_reason = r.reason || 'Pre-check failure';
      }

      summary.plugins.push(pluginSummary);
    }

    // Generate recommendations
    if (summary.failed > 0) {
      summary.recommendations.push('Review failed plugins and resolve blockers before retrying');
      summary.recommendations.push('Check system logs for detailed error information');
    }
    if (summary.skipped > 0) {
      summary.recommendations.push('Use the Skipped Items Review Agent to analyze skipped plugins');
    }
    if (summary.successful > 0) {
      summary.recommendations.push('Monitor upgraded plugins for 24-48 hours for stability');
      summary.recommendations.push('Run integration tests to verify dependent functionality');
    }

    summary.success_rate = summary.total_attempted > 0 ? 
      Math.round((summary.successful / summary.total_attempted) * 100) + '%' : '0%';

    result.summary = summary;
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to generate summary: ' + e.message;
  }
  return result;
})(inputs);
